// Pages to read, one at a time. Edit CATEGORIES in n8n/build-workflow.mjs, not here.
// The Browserless function is n8n/browserless/extract-deals.js, inlined by the build.
const EXTRACT_CODE = "// Browserless /function code: renders one Amazon Brazil deals page and extracts
// the deal cards. Single source of truth for the scraper selectors: the n8n
// workflow inlines this file (n8n/build-workflow.mjs) and the tests run it
// against a saved page (n8n/browserless/__fixtures__/deals.html).
//
// context: { url, maxScrolls?, settleMs?, maxProducts?, timeoutMs? }
// returns (sent as JSON by Browserless): { url, status, scrolls, products }
// Each product has the raw strings of the import payload (specs/product.md):
// { asin, title, url, imageUrl, price, listPrice, discountPercent, rating, reviewCount }

const USER_AGENT =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36";

const CARD = '[data-testid="product-card"]';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Runs inside the page: every selector the scraper depends on is here.
function extractCards(cardSelector) {
  const text = (el) => (el?.textContent ?? "").replace(/\s+/g, " ").trim();
  const money = (el) => {
    const match = text(el).match(/R\$\s?[\d.]+(?:,\d{2})?/);
    return match ? match[0].replace(/\s/g, " ") : null;
  };
  // Amazon may render the title twice in the same element ("AbcAbc")
  const dedupe = (value) => {
    const half = value.length / 2;
    return Number.isInteger(half) && value.slice(0, half) === value.slice(half)
      ? value.slice(0, half).trim()
      : value;
  };

  return Array.from(document.querySelectorAll(cardSelector)).map((card) => {
    const asin = card.getAttribute("data-asin") ?? "";
    const titleEl = card.querySelector(`[id="title-${asin}"]`);
    const img = card.querySelector("img");
    const link = card.querySelector('a[data-testid="product-card-link"]');
    const prices = card.querySelector('[data-testid="price-section"]');
    const badge = text(card.querySelector('[data-component="dui-badge"]'));
    const discount = badge.match(/(\d{1,3})\s?%/);
    const reviews = card.querySelector('[data-testid="review-count-link"]');

    const title =
      text(titleEl?.querySelector(".a-truncate-full")) ||
      dedupe(text(titleEl)) ||
      (img?.getAttribute("alt") ?? "").trim();

    return {
      asin,
      title,
      url: link ? link.href : null,
      imageUrl: img ? img.src : null,
      price: money(
        prices?.querySelector(".a-price:not(.a-text-price) .a-offscreen") ??
          prices?.querySelector(".a-price:not(.a-text-price)"),
      ),
      listPrice: money(
        prices?.querySelector(".a-text-price .a-offscreen") ??
          prices?.querySelector('[data-a-strike="true"]'),
      ),
      discountPercent: discount ? Number(discount[1]) : null,
      rating: text(card.querySelector('[data-testid="review-value"]')) || null,
      // aria-label has the exact count ("2.164 avaliações"); the text is rounded ("(2,2 mil)")
      reviewCount:
        (reviews?.getAttribute("aria-label") ?? "").trim() ||
        text(reviews) ||
        null,
    };
  });
}

export default async function ({ page, context = {} }) {
  const {
    url = "https://www.amazon.com.br/deals",
    maxScrolls = 15,
    settleMs = 1200,
    maxProducts = 150,
    timeoutMs = 45000,
  } = context;

  // Puppeteer (Browserless) and Playwright (tests) name these differently
  if (typeof page.setUserAgent === "function") {
    await page.setUserAgent(USER_AGENT);
  }
  if (typeof page.setViewport === "function") {
    await page.setViewport({ width: 1366, height: 900 });
  } else if (typeof page.setViewportSize === "function") {
    await page.setViewportSize({ width: 1366, height: 900 });
  }
  await page.setExtraHTTPHeaders({ "Accept-Language": "pt-BR,pt;q=0.9" });

  const response = await page.goto(url, {
    waitUntil: "domcontentloaded",
    timeout: timeoutMs,
  });
  const status = response ? response.status() : null;
  await page.waitForSelector(CARD, { timeout: timeoutMs });

  // The grid is virtualized: cards leave the DOM when they scroll out of view, so
  // collect what is rendered at each step while scrolling down a screen at a time.
  // More cards load near the end; stop after a few steps with nothing new.
  const products = new Map();
  let scrolls = 0;
  let stale = 0;
  while (true) {
    const before = products.size;
    for (const card of await page.evaluate(extractCards, CARD)) {
      if (card.asin && !products.has(card.asin)) products.set(card.asin, card);
    }
    stale = products.size > before ? 0 : stale + 1;
    if (scrolls >= maxScrolls || products.size >= maxProducts || stale >= 3) {
      break;
    }
    await page.evaluate(() => window.scrollBy(0, window.innerHeight * 0.8));
    scrolls++;
    await sleep(settleMs);
    await page.waitForSelector(CARD, { timeout: timeoutMs }).catch(() => {});
  }

  return {
    url,
    status,
    scrolls,
    products: [...products.values()].slice(0, maxProducts),
  };
}
";
const CATEGORIES = [["automotive","Automotive"],["baby","Baby"],["beauty","Beauty"],["books","Books"],["computers","Computers"],["eBooks","eBooks"],["electronics","Electronics"],["eletro","Appliances"],["fashion","Fashion"],["grocery","Grocery"],["health-and-personal-care","Health and personal care"],["home","Home"],["kitchen","Kitchen"],["lawn-and-garden","Garden"],["moveis","Furniture"],["office-products","Office"],["pet-products","Pet products"],["sports","Sports"],["tools","Tools"],["toys-and-games","Toys and games"],["tvs","TVs"],["video-games","Video games"]];

if (!$env.PRODUCTS_IMPORT_TOKEN) {
  throw new Error("PRODUCTS_IMPORT_TOKEN is not set for n8n (see n8n/README.md)");
}

const pages = [
  { slug: "deals-all", name: "More deals", url: "https://www.amazon.com.br/deals" },
  ...CATEGORIES.map(([slug, name]) => ({
    slug: "deals-collection-" + slug,
    name,
    url: "https://www.amazon.com.br/deals?bubble-id=deals-collection-" + slug,
  })),
];

// Optional DEALS_CATEGORIES="tvs,books" (or "deals-all") limits the run
const only = String($env.DEALS_CATEGORIES || "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);
const selected = only.length
  ? pages.filter((p) => only.includes(p.slug) || only.includes(p.slug.replace("deals-collection-", "")))
  : pages;

return selected.map((page) => ({
  json: {
    category: { slug: page.slug, name: page.name },
    url: page.url,
    browserless: { code: EXTRACT_CODE, context: { url: page.url, scrolls: 4 } },
  },
}));

// Splits the extracted products into import requests of at most 100.
// A failed or empty page becomes one item without products, so the loop goes on.
const page = $('Each category').itemMatching(0).json;
const result = $input.first().json;
const products = Array.isArray(result.products) ? result.products : [];
const base = { category: page.category, found: products.length };

if (products.length === 0) {
  const error = result.error
    ? result.error.message || JSON.stringify(result.error)
    : "No deal cards found";
  return [{ json: { ...base, products: [], error } }];
}

const items = [];
for (let i = 0; i < products.length; i += 100) {
  items.push({ json: { ...base, products: products.slice(i, i + 100), error: null } });
}
return items;

// One line per import request (or per failed page) for the final summary.
const batch = $('Make batches').item.json;
const response = $json;
const row = {
  category: batch.category.slug,
  found: batch.found,
  sent: batch.products.length,
  saved: 0,
  skipped: 0,
  error: batch.error,
};

if (batch.products.length > 0) {
  if (typeof response.saved === "number") {
    row.saved = response.saved;
    row.skipped = response.skipped.length;
    row.skippedReasons = response.skipped.slice(0, 5);
  } else {
    row.error = response.error
      ? response.error.message || JSON.stringify(response.error)
      : "Import request failed";
  }
}
return { json: row };

// Final summary: categories read, products sent and saved, failures.
const rows = $input.all().map((item) => item.json);
const byCategory = {};
for (const row of rows) {
  const c = (byCategory[row.category] ??= { category: row.category, found: row.found, sent: 0, saved: 0, skipped: 0, errors: [] });
  c.sent += row.sent;
  c.saved += row.saved;
  c.skipped += row.skipped;
  if (row.error) c.errors.push(row.error);
}
const categories = Object.values(byCategory);
const failed = categories.filter((c) => c.errors.length > 0);
const sum = (key) => categories.reduce((total, c) => total + c[key], 0);

return [{
  json: {
    categories: categories.length,
    succeeded: categories.length - failed.length,
    failed: failed.map((c) => ({ category: c.category, errors: c.errors })),
    productsFound: sum("found"),
    productsSent: sum("sent"),
    productsSaved: sum("saved"),
    productsSkipped: sum("skipped"),
    perCategory: categories.map(({ errors, ...c }) => c),
  },
}];
